import { useState } from 'react'
import { useMutation, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import {
  Download,
  Trash2,
  Radar,
  RefreshCw,
  Settings2,
  ArrowUpCircle,
  ExternalLink,
  CheckCircle2,
  XCircle,
  AlertTriangle,
} from 'lucide-react'
import { api } from '@/lib/api'
import type { ToolItem, InstallResult, ProbeResult, UpdateInfo } from '@/lib/api'
import { cn } from '@/lib/utils'
import { Badge, Button, HealthDot, Modal, StatusBadge, Switch, ToolIcon } from './ui'
import { EnvDialog } from './EnvDialog'

interface ToolCardProps {
  tool: ToolItem
}

export function ToolCard({ tool }: ToolCardProps) {
  const queryClient = useQueryClient()
  const [envOpen, setEnvOpen] = useState(false)
  const [confirmUninstall, setConfirmUninstall] = useState(false)
  const [updateInfo, setUpdateInfo] = useState<UpdateInfo | null>(null)
  const [selectedVersion, setSelectedVersion] = useState(
    tool.versions?.[0] || '',
  )

  const isInstalling = tool.status === 'installing' || tool.installing
  const isInstalled = tool.status === 'installed'
  const isFailed = tool.status === 'failed'
  const notInstalled =
    tool.status === 'not_installed' || tool.status === 'uninstalled'
  const isOutdated = (isInstalled || isFailed) && !!tool.outdated

  const hasVersionChoice = (tool.versions?.length ?? 0) > 0
  const showVersionPicker = hasVersionChoice && (notInstalled || isOutdated)

  const invalidate = () => queryClient.invalidateQueries({ queryKey: ['tools'] })

  // 安装 / 更新（覆盖安装）
  const installMutation = useMutation({
    mutationFn: () => api.installTool(tool.key, hasVersionChoice ? selectedVersion : undefined),
    onMutate: () => invalidate(),
    onSuccess: (res: InstallResult) => {
      invalidate()
      if (res.success === false) {
        toast.error(res.error || res.message || '安装失败')
        return
      }
      toast.success(res.message || `${tool.name} 安装成功`)
      setUpdateInfo(null)
      // 若声明了环境变量且尚未配置，弹出配置对话框
      const needsEnv =
        (tool.env_config_keys?.length ?? 0) > 0 &&
        tool.env_config_keys.some((k) => !tool.env_configured?.[k])
      if (needsEnv) setEnvOpen(true)
    },
    onError: (e: Error) => {
      invalidate()
      toast.error(e.message)
    },
  })

  // 卸载
  const uninstallMutation = useMutation({
    mutationFn: () => api.uninstallTool(tool.key),
    onSuccess: (res: InstallResult) => {
      invalidate()
      setConfirmUninstall(false)
      if (res.success === false) {
        toast.error(res.error || res.message || '卸载失败')
        return
      }
      toast.success(res.message || `${tool.name} 已卸载`)
    },
    onError: (e: Error) => {
      invalidate()
      setConfirmUninstall(false)
      toast.error(e.message)
    },
  })

  // 探测
  const probeMutation = useMutation({
    mutationFn: () => api.probeTool(tool.key),
    onSuccess: (res: ProbeResult) => {
      invalidate()
      if (res.error) {
        toast.error(res.error)
        return
      }
      if (res.usable) {
        toast.success(`探测成功${res.version ? `：v${res.version}` : ''}`)
      } else {
        toast.warning(`工具不可用${res.problem ? `（${res.problem}）` : ''}`)
      }
    },
    onError: (e: Error) => toast.error(e.message),
  })

  // 检查更新
  const updateMutation = useMutation({
    mutationFn: () => api.checkToolUpdate(tool.key),
    onSuccess: (res: UpdateInfo) => {
      if (res.error) {
        toast.error(res.error)
        return
      }
      setUpdateInfo(res)
      if (res.has_update) {
        toast.info(`发现新版本 ${res.latest_version}`)
      } else {
        toast.success('已是最新版本')
      }
    },
    onError: (e: Error) => toast.error(e.message),
  })

  // 启用 / 禁用
  const toggleMutation = useMutation({
    mutationFn: (next: boolean) => (next ? api.enableTool(tool.key) : api.disableTool(tool.key)),
    onSuccess: (res, next) => {
      invalidate()
      if (res && res.success === false) {
        toast.error(res.error || '操作失败')
        return
      }
      toast.success(next ? '已启用' : '已禁用')
    },
    onError: (e: Error) => toast.error(e.message),
  })

  const busy =
    isInstalling ||
    installMutation.isPending ||
    uninstallMutation.isPending

  const envKeys = tool.env_config_keys ?? []

  return (
    <>
      <div
        className={cn(
          'flex flex-col rounded-xl border bg-card p-4 transition-all hover:shadow-md',
          isFailed && 'border-red-500/40',
          isInstalling && 'border-blue-500/40',
        )}
      >
        {/* 头部：图标 + 名称 + 版本 */}
        <div className="flex items-start gap-3">
          <div className="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary">
            <ToolIcon name={tool.icon} className="h-5 w-5" />
          </div>
          <div className="min-w-0 flex-1">
            <div className="flex items-center justify-between gap-2">
              <h3 className="truncate font-semibold">{tool.name}</h3>
              {isInstalled && tool.version ? (
                <span className="flex-shrink-0 font-mono text-xs text-muted-foreground">
                  v{tool.version}
                </span>
              ) : (
                <StatusBadge status={tool.status} />
              )}
            </div>
            <p className="mt-0.5 line-clamp-2 text-sm text-muted-foreground">
              {tool.description}
            </p>
          </div>
        </div>

        {/* 失败原因 */}
        {isFailed && tool.problem && (
          <div className="mt-3 flex items-start gap-1.5 rounded-lg bg-red-500/10 px-2.5 py-1.5 text-xs text-red-600 dark:text-red-400">
            <AlertTriangle className="mt-0.5 h-3.5 w-3.5 flex-shrink-0" />
            <span className="break-all">{tool.problem}</span>
          </div>
        )}

        {/* 更新提示 */}
        {updateInfo?.has_update && (
          <div className="mt-3 flex items-center justify-between gap-2 rounded-lg bg-amber-500/10 px-2.5 py-1.5 text-xs text-amber-600 dark:text-amber-400">
            <span className="flex items-center gap-1.5">
              <ArrowUpCircle className="h-3.5 w-3.5" />
              新版本 {updateInfo.latest_version}
            </span>
            <Button
              size="xs"
              variant="primary"
              loading={installMutation.isPending}
              disabled={busy}
              onClick={() => installMutation.mutate()}
            >
              更新
            </Button>
          </div>
        )}

        {/* 已安装：状态行 */}
        {isInstalled && (
          <div className="mt-3 flex flex-wrap items-center gap-x-3 gap-y-2">
            {isOutdated ? (
              <Badge tone="amber">
                <AlertTriangle className="h-3 w-3" />
                版本过低 ({tool.version})
              </Badge>
            ) : (
              <Badge tone="green">
                <CheckCircle2 className="h-3 w-3" />
                已安装
              </Badge>
            )}
            <HealthDot healthy={tool.healthy} />
            <div className="ml-auto flex items-center gap-2">
              <span className="text-xs text-muted-foreground">
                {tool.enabled ? '已启用' : '已禁用'}
              </span>
              <Switch
                checked={tool.enabled}
                disabled={busy || toggleMutation.isPending}
                onChange={(next) => toggleMutation.mutate(next)}
                label={`启用 ${tool.name}`}
              />
            </div>
          </div>
        )}

        {/* 失败态：版本过低或安装失败 */}
        {isFailed && (
          <div className="mt-3 flex items-center gap-3">
            {isOutdated ? (
              <Badge tone="amber">
                <AlertTriangle className="h-3 w-3" />
                版本过低 ({tool.version})
              </Badge>
            ) : (
              <Badge tone="red">
                <XCircle className="h-3 w-3" />
                安装失败
              </Badge>
            )}
            <HealthDot healthy={false} />
          </div>
        )}

        {/* 环境变量概览 */}
        {isInstalled && envKeys.length > 0 && (
          <div className="mt-3 flex flex-wrap items-center gap-1.5 border-t pt-3">
            <span className="text-xs text-muted-foreground">环境变量:</span>
            {envKeys.map((k) => {
              const ok = !!tool.env_configured?.[k]
              return (
                <span
                  key={k}
                  className={cn(
                    'inline-flex items-center gap-1 rounded bg-muted px-1.5 py-0.5 font-mono text-[11px]',
                    ok ? 'text-green-600 dark:text-green-400' : 'text-muted-foreground',
                  )}
                >
                  {ok ? <CheckCircle2 className="h-3 w-3" /> : <XCircle className="h-3 w-3" />}
                  {k}
                </span>
              )
            })}
          </div>
        )}

        {/* 未安装提示 */}
        {notInstalled && !tool.can_auto_install && !hasVersionChoice && tool.install_hint && (
          <p className="mt-3 rounded-lg bg-muted/50 px-2.5 py-2 text-xs text-muted-foreground">
            {tool.install_hint}
          </p>
        )}

        {/* 版本选择器（未安装或版本过低时显示） */}
        {showVersionPicker && (
          <div className="mt-3 flex items-center gap-2">
            <span className="text-xs text-muted-foreground">安装版本:</span>
            <div className="flex gap-1">
              {tool.versions.map((v) => (
                <button
                  key={v}
                  onClick={() => setSelectedVersion(v)}
                  className={`rounded-md px-2 py-0.5 text-xs font-mono transition-colors ${
                    selectedVersion === v
                      ? 'bg-primary text-primary-foreground'
                      : 'bg-muted text-muted-foreground hover:bg-muted/80'
                  }`}
                >
                  {v === tool.versions[0] ? `${v} (最新)` : v}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* 版本过低提示 */}
        {isOutdated && tool.min_version && (
          <p className="mt-2 rounded-lg bg-amber-500/10 px-2.5 py-1.5 text-xs text-amber-600 dark:text-amber-400">
            最低要求 v{tool.min_version}，当前 v{tool.version}。请选择版本后升级。
          </p>
        )}

        {/* 操作区 */}
        <div className="mt-4 flex flex-wrap items-center gap-2">
          {isInstalling ? (
            <span className="inline-flex items-center gap-2 text-sm text-blue-600 dark:text-blue-400">
              <RefreshCw className="h-4 w-4 animate-spin" />
              正在安装...
            </span>
          ) : notInstalled ? (
            <>
              {tool.can_auto_install || hasVersionChoice ? (
                <Button
                  variant="primary"
                  loading={installMutation.isPending}
                  onClick={() => installMutation.mutate()}
                >
                  <Download className="h-3.5 w-3.5" />
                  {hasVersionChoice ? `安装 ${selectedVersion}` : '安装'}
                </Button>
              ) : (
                <span className="text-xs text-muted-foreground">暂不支持自动安装</span>
              )}
              {tool.install_hint && /^https?:\/\//.test(tool.install_hint) && (
                <a
                  href={tool.install_hint}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-1 text-xs text-primary hover:underline"
                >
                  <ExternalLink className="h-3.5 w-3.5" />
                  访问官方链接安装
                </a>
              )}
            </>
          ) : isOutdated ? (
            <>
              <Button
                variant="primary"
                loading={installMutation.isPending}
                disabled={busy}
                onClick={() => installMutation.mutate()}
              >
                <ArrowUpCircle className="h-3.5 w-3.5" />
                升级到 {selectedVersion}
              </Button>
              <Button
                size="xs"
                loading={probeMutation.isPending}
                disabled={busy}
                onClick={() => probeMutation.mutate()}
              >
                <Radar className="h-3.5 w-3.5" />
                探测
              </Button>
            </>
          ) : isFailed ? (
            <>
              {(tool.can_auto_install || hasVersionChoice) && (
                <Button
                  variant="primary"
                  loading={installMutation.isPending}
                  disabled={busy}
                  onClick={() => installMutation.mutate()}
                >
                  <Download className="h-3.5 w-3.5" />
                  重新安装
                </Button>
              )}
              <Button
                size="xs"
                loading={probeMutation.isPending}
                disabled={busy}
                onClick={() => probeMutation.mutate()}
              >
                <Radar className="h-3.5 w-3.5" />
                探测
              </Button>
              <Button
                size="xs"
                variant="danger"
                disabled={busy}
                onClick={() => setConfirmUninstall(true)}
              >
                <Trash2 className="h-3.5 w-3.5" />
                清除记录
              </Button>
            </>
          ) : (
            <>
              <Button
                size="xs"
                loading={probeMutation.isPending}
                disabled={busy}
                onClick={() => probeMutation.mutate()}
              >
                <Radar className="h-3.5 w-3.5" />
                探测
              </Button>
              <Button
                size="xs"
                loading={updateMutation.isPending}
                disabled={busy}
                onClick={() => updateMutation.mutate()}
              >
                <RefreshCw className="h-3.5 w-3.5" />
                检查更新
              </Button>
              <Button size="xs" disabled={busy} onClick={() => setEnvOpen(true)}>
                <Settings2 className="h-3.5 w-3.5" />
                配置
              </Button>
              <Button
                size="xs"
                variant="danger"
                disabled={busy}
                onClick={() => setConfirmUninstall(true)}
              >
                <Trash2 className="h-3.5 w-3.5" />
                卸载
              </Button>
            </>
          )}
        </div>
      </div>

      {/* 卸载确认 */}
      <Modal
        open={confirmUninstall}
        onClose={() => setConfirmUninstall(false)}
        title="确认卸载"
        width="max-w-sm"
        footer={
          <>
            <Button
              variant="ghost"
              onClick={() => setConfirmUninstall(false)}
              disabled={uninstallMutation.isPending}
            >
              取消
            </Button>
            <Button
              variant="danger"
              loading={uninstallMutation.isPending}
              onClick={() => uninstallMutation.mutate()}
            >
              卸载
            </Button>
          </>
        }
      >
        <p className="text-sm text-muted-foreground">
          确定要卸载 <span className="font-medium text-foreground">{tool.name}</span> 吗？
          此操作会移除该工具的二进制与配置。
        </p>
      </Modal>

      {/* 环境变量配置 */}
      <EnvDialog tool={tool} open={envOpen} onClose={() => setEnvOpen(false)} />
    </>
  )
}
